class User with MaybeCopyWith<User> {
  final String name;
  final String? gender;

  const User({required this.name, this.gender});

  @override
  User copyWith({
    String? name,
    Maybe<String>? gender,
  }) {
    return User(
      name: name ?? this.name,
      gender: gender.or(this.gender),
    );
  }
}
